function renderProducts(){const query=$("hfProductSearch").value.trim().toLowerCase(),filter=$("hfProductFilter").value;const rows=products.filter(p=>(filter==="all"||(filter==="active"&&p.is_active)||(filter==="archived"&&!p.is_active))&&(!query||[p.name,p.sku,p.attributes?.barcode,p.attributes?.brand,categoryName(p)].join(" ").toLowerCase().includes(query)));
