function render(){ $("hfCatalogTitle").textContent=(website.brand?.name||website.name)+" · Products & Categories";$("hfCatalogPages").href="./website-pages.html?template="+encodeURIComponent(templateKey);$("hfCatalogOrders").href="./website-orders.html?template="+encodeURIComponent(templateKey);$("hfCatalogPreview").href="../storefront.html?site="+encodeURIComponent(website.slug)+(website.status==="published"?"":"&preview=1");$("hfCatalogPreview").textContent=website.status==="published"?"Open live website ↗":"Open private preview ↗";$("hfCatalogPreview").classList.toggle("is-live",website.status==="published");$("hfCatalogPreview").title=website.status==="published"?"Open the public storefront in a new tab":"Open the private owner preview; publish the website to make it public.";fillCategoryOptions();renderStats();renderCategories();renderProducts();fillOperationsForm();}
